window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["vector-db"]={"title":"向量数据库：在大规模嵌入中做近似近邻检索","subtitle":"理解向量、距离度量、HNSW/IVF/PQ、过滤、更新与一致性，并把索引 Recall、延迟和端到端 RAG 分开。","thesis":"向量数据库把对象嵌入为向量并用近似最近邻索引加速相似搜索；它管理的不只是向量，还包括<b>标识、元数据、权限、版本和原文映射</b>，近似索引需用召回—延迟—内存权衡。","quality":{"contractVersion":2,"examples":[{"section":7,"evidence":{"setup":"一百万个 768 维向量","rule":"必须用精确搜索作为离线基准","steps":"ANN top-10","interpretation":"只说明近似索引复现了精确向量排序"}}],"formulas":[],"termReviews":[{"section":3,"reviewedAt":"2026-07-27","terms":[{"name":"HNSW","meaning":"沿多层邻接图导航的近似近邻索引","purpose":"减少大规模搜索需要访问的向量节点","definitionEvidence":"HNSW 沿多层邻接图导航","purposeEvidence":"它们减少访问或存储"},{"name":"IVF","meaning":"先用粗聚类桶缩小候选范围的索引","purpose":"避免对全库向量逐个比较","definitionEvidence":"IVF 先选粗聚类桶","purposeEvidence":"减少访问或存储以换取可能漏掉真近邻"},{"name":"PQ","meaning":"用短码近似保存与比较向量的压缩方法","purpose":"降低向量载荷和距离计算成本","definitionEvidence":"PQ 用短码近似向量","purposeEvidence":"减少访问或存储以换取可能漏掉真近邻"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"向量数据库用嵌入作为检索键并管理原文元数据权限和版本。","evidence":"向量只是一种检索键"},"problem":{"answer":"它解决大规模相似候选访问及其原文回填问题。","evidence":"存进向量后，原文和权限去哪了"},"inputOutput":{"answer":"输入向量和治理字段，输出相似候选及可取回原文。","evidence":"输出相似候选及可取回的原始内容"},"mechanism":{"answer":"先按向量找候选，再回原文并按当前主体鉴权。","evidence":"命中后仍需回原文并按当前主体鉴权"},"interpretation":{"answer":"高相似度表示空间接近，不表示事实可信。","evidence":"不表示事实可信"},"boundary":{"answer":"缺原文映射或权限字段的向量不能直接服务回答。","evidence":"不能直接服务回答"}},{"section":2,"definition":{"answer":"余弦、点积和欧氏距离是不同的向量排序度量。","evidence":"距离与归一化"},"problem":{"answer":"它说明三种距离何时产生相同邻居排序。","evidence":"余弦、点积和欧氏距离何时等价"},"inputOutput":{"answer":"输入向量、归一化和模型约定，输出距离排序。","evidence":"输出余弦、点积或欧氏距离排序"},"mechanism":{"answer":"归一化后按方向比较，未归一化点积还受模长影响。","evidence":"未归一化时向量模长会改变点积"},"interpretation":{"answer":"距离分数表示模型空间关系，不是答案正确概率。","evidence":"分数不能当正确概率"},"boundary":{"answer":"度量必须匹配嵌入模型的训练与使用方式。","evidence":"度量必须与模型训练方式一致"}},{"section":3,"definition":{"answer":"ANN 用索引近似寻找向量空间中的最近邻。","evidence":"为什么使用近似索引"},"problem":{"answer":"它避免精确全库扫描随向量数量线性增长。","evidence":"全库逐个比较为什么不可扩展"},"inputOutput":{"answer":"输入向量库和查询，输出近似 topK 邻居。","evidence":"输出近似 topK 邻居"},"mechanism":{"answer":"HNSW 导航图、IVF 选桶、PQ 压缩后搜索。","evidence":"HNSW 沿多层邻接图导航"},"interpretation":{"answer":"更少访问和存储以可能漏掉真正近邻为代价。","evidence":"换取可能漏掉真近邻"},"boundary":{"answer":"小数据或必须精确的任务可直接用全量搜索。","evidence":"不能为“先进”强行近似"}},{"section":4,"definition":{"answer":"索引参数控制近似召回、延迟、内存和构建成本。","evidence":"索引参数的三角"},"problem":{"answer":"它指导 HNSW 的 ef 和 IVF probes 如何取值。","evidence":"怎样调 HNSW 的 ef 或 IVF 的 probes"},"inputOutput":{"answer":"输入参数与查询集，输出多维权衡曲线。","evidence":"输出 Recall、延迟、内存及构建成本曲线"},"mechanism":{"answer":"增加搜索广度并与精确邻居逐查询对照。","evidence":"搜索更广通常提升召回同时增加资源"},"interpretation":{"answer":"选点应满足证据召回和 SLO，而非只追求 QPS。","evidence":"不是最大化单一 QPS"},"boundary":{"answer":"参数变化后必须重新运行精确基准比较。","evidence":"必须和精确邻居重新对照"}},{"section":5,"definition":{"answer":"过滤感知检索在允许候选域内找相似结果。","evidence":"过滤检索输入查询、租户与权限条件"},"problem":{"answer":"它避免全局 topK 后过滤把结果全部删除。","evidence":"为何可能一个结果都没有"},"inputOutput":{"answer":"输入查询权限和 k，输出允许域候选并再次鉴权。","evidence":"输出只在允许候选域内搜索的结果"},"mechanism":{"answer":"索引按过滤条件扩大或限制搜索，返回时权威复核。","evidence":"返回原文前再次权威鉴权"},"interpretation":{"answer":"过滤改善候选覆盖，不等于已经完成授权。","evidence":"不等于完成授权"},"boundary":{"answer":"敏感原文不能只依赖索引元数据决定访问。","evidence":"不能只信索引元数据"}},{"section":6,"definition":{"answer":"版本与删除管理保证同一查询只比较同一嵌入空间。","evidence":"更新、删除与版本"},"problem":{"answer":"它处理换嵌入模型后旧向量不可直接混用的问题。","evidence":"换嵌入模型后旧向量还能混用吗"},"inputOutput":{"answer":"输入变更删除和版本，输出重建切换或删除状态。","evidence":"输出新命名空间、双写重建、原子切换或全链路删除状态"},"mechanism":{"answer":"新版本独立重建并原子切换，删除沿副本缓存传播。","evidence":"不同嵌入版本属于不同几何空间"},"interpretation":{"answer":"传播未完成表示查询仍可能命中陈旧或幽灵内容。","evidence":"结果必须标记陈旧或停止服务"},"boundary":{"answer":"跨版本距离不可直接比较，删除也不能只删主索引。","evidence":"分数不能混比"}},{"section":7,"definition":{"answer":"规模案例比较百万向量精确扫描与 HNSW 近似搜索。","evidence":"百万向量为什么需要索引"},"problem":{"answer":"它量化原始内存、计算量和近似索引的召回代价。","evidence":"精确扫描究竟付出多少存储和比较"},"inputOutput":{"answer":"输入百万向量与两组 top10，输出内存计算和索引召回。","evidence":"输出约 3.07GB 原始载荷、768M 维度乘加和索引 Recall10"},"mechanism":{"answer":"把 ANN top10 与精确 top10 求交并除以十。","evidence":"ANN 命中精确集合 9 条得到 90%"},"interpretation":{"answer":"百分之九十只衡量索引复现精确向量排序。","evidence":"只说明近似索引复现精确向量排序"},"boundary":{"answer":"嵌入本身漏掉正确证据时高索引召回无法修复。","evidence":"索引 Recall 再高也无用"}},{"section":8,"definition":{"answer":"一致性链路让过滤更新撤权删除和版本穿过所有副本。","evidence":"过滤、版本与删除怎样穿过全链路"},"problem":{"answer":"它解释低权限占比时全局 topK 后过滤为何失败。","evidence":"为什么几乎注定失败"},"inputOutput":{"answer":"输入过滤率和事件，输出候选及可审计传播状态。","evidence":"输出过滤感知候选和可审计传播状态"},"mechanism":{"answer":"过滤感知搜索候选，生命周期事件按状态机传播。","evidence":"全局 top10 期望仅 0.1 条属于该租户"},"interpretation":{"answer":"期望零点一是容量直觉，不是单次查询结果保证。","evidence":"不是单次查询保证"},"boundary":{"answer":"返回边界仍需按当前主体资源动作重新鉴权。","evidence":"必须按当前主体、资源和动作鉴权"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>区分精确与 ANN；解释 HNSW/IVF/PQ；设计元数据过滤；管理嵌入版本和删除。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>向量只是一种检索键<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">存进向量后，原文和权限去哪了？</p><p>每个向量必须关联稳定文档/分块 id、元数据和原文位置。向量用于找候选，答案仍需取回原内容并做权限校验。</p><p>容量规划要使用真实向量数、维度、数据类型、索引边数、副本数和增长率，而不只看原始文件大小。上线前保存一组精确近邻基准查询，并按租户过滤率、语言、文档新旧和难度切片；每次调整 ef、probes、量化或分片后同时复测 Recall、p95/p99 延迟、内存和空结果率，才能区分“索引更快”与“业务证据仍可找到”。</p><p>向量数据库输入对象嵌入、稳定 ID、原文位置、元数据、权限和版本，输出相似候选及可取回的原始内容。向量只是搜索键，命中后仍需回原文并按当前主体鉴权；高相似度表示表示空间接近，不表示事实可信。缺少原文映射或权限字段的向量不能直接服务回答。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>距离与归一化<span class=\"dd-badge math\">数学</span></h2><p class=\"dd-lead\">余弦、点积和欧氏距离何时等价？</p><p>向量 L2 归一化后，最大点积、最大余弦与最小平方欧氏距离排序等价。未归一化时模长会影响点积，必须与嵌入模型训练方式一致。</p><p>距离选择输入查询向量、候选向量、是否 L2 归一化及嵌入模型约定，输出余弦、点积或欧氏距离排序。归一化后最大点积、最大余弦和最小平方欧氏距离排序等价；未归一化时向量模长会改变点积。度量必须与模型训练方式一致，分数不能当正确概率。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>为什么使用近似索引<span class=\"dd-badge eng\">ANN</span></h2><p class=\"dd-lead\">全库逐个比较为什么不可扩展？</p><p>精确搜索成本随库大小线性增长。HNSW 建多层邻接图快速导航；IVF 先找粗聚类桶；PQ 压缩向量。它们用少量召回损失换延迟和内存。</p><p>ANN 索引输入大量向量和查询，输出近似 topK 邻居。HNSW 沿多层邻接图导航，IVF 先选粗聚类桶，PQ 用短码近似向量；它们减少访问或存储以换取可能漏掉真近邻。数据量小或必须精确时可用全量搜索，不能为“先进”强行近似。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>索引参数的三角<span class=\"dd-badge math\">权衡</span></h2><p class=\"dd-lead\">怎样调 HNSW 的 ef 或 IVF 的 probes？</p><p>搜索更广通常提高 Recall@k，也增加延迟；建图连边和量化精度影响内存与构建。用目标查询集对比精确结果，画 Recall—latency—memory 曲线。</p><p>索引调参输入 HNSW 的 ef、IVF 的 probes、图边、量化精度和目标查询集，输出 Recall、延迟、内存及构建成本曲线。搜索更广通常提升召回同时增加资源；选点应满足业务证据召回和 SLO，而不是最大化单一 QPS。参数变化后必须和精确邻居重新对照。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>过滤与权限<span class=\"dd-badge eng\">安全</span></h2><p class=\"dd-lead\">先向量搜再过滤为何可能一个结果都没有？</p><p>后过滤会把 top-k 中无权结果删光；前过滤可能破坏索引效率。需要过滤感知搜索或扩大候选，但真正鉴权仍在返回前执行，不能信任模型。</p><p>过滤检索输入查询、租户与权限条件和目标 k，输出只在允许候选域内搜索的结果，并在返回原文前再次权威鉴权。全局 topK 后过滤会把无权结果删光，前过滤又可能降低索引效率；过滤感知搜索解决候选覆盖，不等于完成授权。任何敏感内容都不能只信索引元数据。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>更新、删除与版本<span class=\"dd-badge eng\">运维</span></h2><p class=\"dd-lead\">换嵌入模型后旧向量还能混用吗？</p><p>不同模型/版本的空间不可直接比较。索引记录 embedding 版本，双写重建并原子切换；删除覆盖向量、元数据、缓存和副本，监控陈旧与孤儿记录。</p><div class=\"dd-note warn\"><b>高向量相似度不等于事实相关或可信。</b></div><p>生命周期管理输入文档变更、删除、嵌入版本和缓存副本，输出新命名空间、双写重建、原子切换或全链路删除状态。不同嵌入版本属于不同几何空间，分数不能混比；删除完成需覆盖向量、原文、缓存和副本。传播未完成时结果必须标记陈旧或停止服务。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>百万向量为什么需要索引<span class=\"dd-badge math\">运行示例</span></h2><p class=\"dd-lead\">一百万个 768 维向量，精确扫描究竟付出多少存储和比较？HNSW 又牺牲了什么？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 680 230\" role=\"img\" aria-label=\"精确向量扫描与 HNSW 分层近邻图搜索对比\"><defs><marker id=\"vd1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#6b7484\"/></marker></defs><text x=\"20\" y=\"28\" class=\"svg-t\">精确扫描：查询与全部 1,000,000 个点比较</text><rect x=\"20\" y=\"42\" width=\"250\" height=\"64\" rx=\"8\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"145\" y=\"66\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">768M 维度乘加 / query</text><text x=\"145\" y=\"86\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">结果精确 · 成本随 N 线性增长</text><path d=\"M270,74 L330,74\" stroke=\"#6b7484\" marker-end=\"url(#vd1)\"/><text x=\"350\" y=\"28\" class=\"svg-t\">HNSW：从稀疏层跳到局部密集层</text><rect x=\"350\" y=\"42\" width=\"310\" height=\"166\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"373\" y=\"68\" class=\"svg-t\" font-size=\"10\">L2 稀疏层</text><circle cx=\"455\" cy=\"64\" r=\"7\" fill=\"#d3a05a\"/><circle cx=\"558\" cy=\"64\" r=\"7\" fill=\"#6b8cbe\"/><path d=\"M462,64 L551,64\" stroke=\"#6b7484\" marker-end=\"url(#vd1)\"/><text x=\"373\" y=\"112\" class=\"svg-t\" font-size=\"10\">L1 中间层</text><circle cx=\"431\" cy=\"108\" r=\"6\" fill=\"#6b8cbe\"/><circle cx=\"493\" cy=\"108\" r=\"6\" fill=\"#6b8cbe\"/><circle cx=\"558\" cy=\"108\" r=\"6\" fill=\"#6b8cbe\"/><circle cx=\"620\" cy=\"108\" r=\"6\" fill=\"#6b8cbe\"/><path d=\"M437,108 L487,108 M499,108 L552,108 M564,108 L614,108\" stroke=\"#6b7484\"/><text x=\"373\" y=\"157\" class=\"svg-t\" font-size=\"10\">L0 密集层</text><circle cx=\"416\" cy=\"154\" r=\"5\" fill=\"#6b8cbe\"/><circle cx=\"449\" cy=\"172\" r=\"5\" fill=\"#6b8cbe\"/><circle cx=\"480\" cy=\"150\" r=\"5\" fill=\"#6b8cbe\"/><circle cx=\"515\" cy=\"174\" r=\"5\" fill=\"#d3a05a\"/><circle cx=\"548\" cy=\"148\" r=\"5\" fill=\"#6b8cbe\"/><circle cx=\"582\" cy=\"174\" r=\"5\" fill=\"#6b8cbe\"/><circle cx=\"616\" cy=\"150\" r=\"5\" fill=\"#6b8cbe\"/><path d=\"M421,156 L444,169 L475,152 L510,171 L544,150 L578,171 L612,152\" fill=\"none\" stroke=\"#6b7484\"/><path d=\"M558,71 C556,89 541,91 558,102 M558,114 C548,132 527,145 518,168\" fill=\"none\" stroke=\"#d3a05a\" marker-end=\"url(#vd1)\"/><text x=\"505\" y=\"198\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">只扩展有希望的邻居；更快，但可能错过真正最近点</text><text x=\"20\" y=\"153\" class=\"svg-t\" font-size=\"10\">ANN 验收：把近似 top-k 与精确 top-k 对比</text><text x=\"20\" y=\"176\" class=\"svg-t\" font-size=\"10\">Recall@10 = |ANN₁₀ ∩ Exact₁₀| / 10</text><text x=\"20\" y=\"199\" class=\"svg-t\" font-size=\"10\">例如命中 9 个：Recall@10 = 90%</text></svg><figcaption>图 1　HNSW 用分层邻接图减少访问节点数；“近似”是显式的召回—延迟取舍，必须用精确搜索作为离线基准。</figcaption></figure><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>项目</th><th>计算</th><th>结果</th><th>还未计入</th></tr></thead><tbody><tr><td>原始向量内存</td><td>1,000,000×768×4 byte</td><td>约 3.07 GB（2.86 GiB）</td><td>图边、id、元数据、allocator</td></tr><tr><td>一次精确点积</td><td>1,000,000×768</td><td>768M 维度乘加</td><td>取 top-k、内存搬运</td></tr><tr><td>ANN top-10</td><td>近似集命中精确集 9 条</td><td>Recall@10=90%</td><td>证据相关性与答案质量</td></tr><tr><td>向量压缩 8 bit</td><td>768×1 byte/向量</td><td>原始载荷约 0.77 GB</td><td>量化码本和精度损失</td></tr></tbody></table></div><p>内存计算揭示“只存 3 GB”仍是低估：HNSW 每点的邻接边、元数据索引、副本和服务开销会继续放大占用。PQ 或标量量化能降低载荷，却改变距离近似；因此应在真实查询集上共同画 Recall、p95 延迟、内存和构建时间曲线，而不是只比较数据库宣传的 QPS。</p><div class=\"dd-note key\"><b>分层指标：</b>ANN Recall@10=90% 只说明近似索引复现了精确向量排序的 90%；如果嵌入本身没有把正确证据排进精确 top-10，索引 Recall 再高也无法修复语义表示。</div><p>规模案例输入一百万个 768 维 FP32 向量、精确 top10 与 ANN top10，输出约 3.07GB 原始载荷、768M 维度乘加和索引 Recall10。ANN 命中精确集合 9 条得到 90%，只说明近似索引复现精确向量排序；如果嵌入没把正确证据排进精确 top10，索引 Recall 再高也无用。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>过滤、版本与删除怎样穿过全链路<span class=\"dd-badge eng\">一致性边界</span></h2><p class=\"dd-lead\">一个用户只能看 1% 的文档时，先取全局 top-10 再过滤为什么几乎注定失败？</p><p>假设全库 100 万块中，租户 A 只有 1 万块（1%）。若相似候选与租户近似独立，全局 top-10 中属于 A 的期望数量仅 <code>10×1%=0.1</code>；后过滤很可能返回空集。把 top-k 扩到 100，期望也只有 1 条，并且扫描、网络和泄露风险都上升。正确方案应让索引搜索感知租户/权限过滤，返回前再由权威鉴权层复核。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>生命周期事件</th><th>必须同步的对象</th><th>可观测不变量</th><th>失败表现</th></tr></thead><tbody><tr><td>文档更新</td><td>原文、块、向量、版本、缓存</td><td>活动版本只有一套可检索映射</td><td>新旧条款同时命中</td></tr><tr><td>权限撤销</td><td>元数据过滤与权威 ACL</td><td>撤销后查询无法取回原文</td><td>向量命中后越权回填</td></tr><tr><td>文档删除</td><td>主索引、副本、缓存、备份策略</td><td>无孤儿向量与可访问缓存</td><td>“幽灵”片段继续被引用</td></tr><tr><td>嵌入升级</td><td>独立命名空间与查询编码器</td><td>同一请求只比较同版本空间</td><td>分数无意义、召回突降</td></tr></tbody></table></div><p>安全删除通常是异步流程，但必须有完成状态、重试、审计和最大传播时间。蓝绿重建时，用新编码器写入新命名空间，离线回归后原子切换查询别名；不要在同一索引中逐条用新向量覆盖旧向量，因为过渡期查询向量无法同时解释两个几何空间。</p><div class=\"dd-note warn\"><b>失败边界：</b>元数据过滤是缩小候选的检索条件，不是最终授权。索引配置错误、缓存遗漏或复制延迟都可能绕过它；敏感原文必须在取回/返回边界再次根据当前主体、资源和动作做鉴权。</div><p>一致性案例输入 1% 租户过滤率和 topK、更新、撤权、删除及嵌入升级事件，输出过滤感知候选和可审计传播状态。全局 top10 期望仅 0.1 条属于该租户，说明后过滤很可能为空；这是假设独立时的容量直觉，不是单次查询保证。返回边界仍必须按当前主体、资源和动作鉴权。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">9</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与路线</span></h2><p class=\"dd-lead\">向量数据库解决的是大规模相似候选访问，不负责理解、证明或授权答案。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>常见误解</th><th>更准确的理解</th></tr></thead><tbody><tr><td>向量库就是普通数据库多一列向量</td><td>还需管理 ANN 索引、召回/延迟参数、版本、过滤和原文映射</td></tr><tr><td>相似度 0.9 表示 90% 正确</td><td>相似分数不是校准概率，也不证明事实相关或可信</td></tr><tr><td>ANN 召回高说明 RAG 检索好</td><td>它只衡量近似索引复现精确向量邻居，未衡量证据相关性</td></tr><tr><td>换嵌入模型可逐条覆盖</td><td>不同空间不可混比，应建立独立版本并原子切换</td></tr><tr><td>元数据过滤等于完成鉴权</td><td>过滤改善候选，权威权限仍须在返回原文前执行</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>嵌入、余弦/点积、切块、检索</td></tr><tr><td><b>本页核心</b></td><td>精确近邻、HNSW/IVF/PQ、索引 Recall、过滤和版本迁移</td></tr><tr><td>紧邻</td><td>RAG、重排、上下文工程、权限治理</td></tr><tr><td>工程延伸</td><td>高级 RAG、量化、可观测性、数据漂移和隐私删除</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">10</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>文档切分并生成版本化嵌入</li><li>写入向量与原文元数据</li><li>ANN 找相似候选</li><li>过滤权限和时效</li><li>取回原文并重排</li><li>以索引和最终答案双层评测</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">11</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>向量库还需存什么？</li><li>为何用 ANN？</li><li>HNSW 是什么结构？</li><li>后过滤风险？</li><li>换嵌入模型怎么办？</li><li>假设“向量数据库：在大规模嵌入中做近似近邻检索”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“向量数据库：在大规模嵌入中做近似近邻检索”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li><li>为什么不能只用一个平均分判断“向量数据库：在大规模嵌入中做近似近邻检索”已经可靠？应怎样按场景切片并设置失败边界？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>id、原文映射、元数据、权限和版本。</li><li>避免全库线性精确比较。</li><li>多层近邻图。</li><li>候选被删光导致召回低。</li><li>重建独立版本并切换，不能混用。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li><li>平均分会隐藏少数类别、极端输入、成本、延迟和安全失败。至少按难度、输入类型、长度或规模、风险等级及已知边界切片，同时报告质量、资源和失败率；高风险硬约束不能被其他切片的高分抵消。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/1603.09320\" target=\"_blank\" rel=\"noopener\">Efficient and robust approximate nearest neighbor search using HNSW</a>：HNSW</li><li><a href=\"https://arxiv.org/abs/1702.08734\" target=\"_blank\" rel=\"noopener\">Billion-scale similarity search with GPUs</a>：FAISS</li><li><a href=\"https://proceedings.neurips.cc/paper/2019/hash/09853c7fb1d3f8ee67a61b6bf4a7f8e6-Abstract.html\" target=\"_blank\" rel=\"noopener\">DiskANN</a>：磁盘级 ANN</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
